// Minimal sketch of a per-tenant window aggregator
class TenantWindow {
  constructor(windowMs) { this.windowMs = windowMs; this.buckets = new Map(); }
  add(evt) { const w = Math.floor(evt.ts / this.windowMs); const key = evt.tenantId + ':' + w; if (!this.buckets.has(key)) this.buckets.set(key, []); this.buckets.get(key).push(evt.latency); }
  estimate(key) { const arr = this.buckets.get(key) || []; // tdigest or percentile calc
  return percentile(arr, 95);
  }
}
```

